pub enum MidiEvent {
    /// Represents a NoteOn MIDI event.
    NoteOn {
        /// The MIDI channel.
        channel: u8,
        /// The MIDI note.
        note: u8,
        /// The velocity of the note.
        velocity: u8,
        /// Duration in ticks.
        duration: u8,
    },
    /// Represents a ControlChange MIDI event.
    ControlChange {
        /// The MIDI channel.
        channel: u8,
        /// The controller number.
        controller: u8,
        /// The control value.
        value: u8,
    },
}

