    pub fn handle_input(&mut self, key: char) -> bool {
        if self.receptors.contains_key(&key) {
            self.input_buffer.push_back(key);
            true
        } else {
            false
        }
    }

    #[cfg(feature = "nova")]
    fn handle_input_interrupts(&mut self) {
        self.sonar_target = None;
        if let Some(key) = self.input_buffer.pop_front() {
            if let Some(&strand_idx) = self.receptors.get(&key) {
                self.call_stack.push(self.ip);

                if strand_idx < self.dna.helix.strands.len() {
                    self.ip = (strand_idx, 0);
                    self.output.push(format!(
                        "INTERRUPT: Signal '{}' -> Strand {}",
                        key, strand_idx
                    ));
                }
            }
        }
    }

    #[cfg(feature = "cortex")]
    fn update_cortex_state(&mut self) {
        for level in self.activation_levels.iter_mut() {
            if *level > 0 {
                *level -= 1;
            }
        }
    }

    /// Updates the environmental simulation layers.
    ///
    /// This simulation runs every tick (unless frozen) and handles:
    /// - **Waste**: Accumulation from metabolic processes.
    /// - **Diffusion**: Spreading of Hormones, Waste, Light, Mutagen, and Entropy.
    /// - **Scent**: Tracking pheromone trails.
    /// - **Fluid Dynamics**: Updating liquid flow and pressure.
    /// - **Mutation**: Triggering random genetic changes if local Toxicity or Radiation is high.
    /// - **Reality Decay**: Triggering Glitches if local Entropy is critical.
    fn check_starvation(&mut self) -> bool {
        if self.energy <= 0 {
            self.halted = true;
            self.output.push("DEATH: STARVATION".to_string());
            true
        } else {
            #[cfg(feature = "nova")]
            if self.energy < 10 {
                self.trigger_reflex(2); // Event 2: Low Energy
            }
            false
        }
    }

    #[cfg(feature = "nova")]
    fn check_telomeres(&mut self) -> bool {
        if self.ip.1 == 0 && self.ip.0 < self.telomeres.len() {
            let degrade = self.phase != nova::Phase::Crystalline;

            if degrade && self.telomeres[self.ip.0] > 0 {
                self.telomeres[self.ip.0] -= 1;
            }

            if self.telomeres[self.ip.0] <= 0 {
                self.output
                    .push(format!("SENESCENCE: Strand {} decayed", self.ip.0));
                self.ip.0 += 1;
                self.ip.1 = 0;
                return true;
            }
        }
        false
    }

    fn pre_tick_updates(&mut self) -> bool {
        if self.halted {
            return false;
        }

        self.tick_counter += 1;

        #[cfg(feature = "nova")]
        {
            self.midi_messages.clear();
            if self.grid_history.len() >= MAX_HISTORY_DEPTH {
                self.grid_history.pop_front();
            }
            self.grid_history.push_back(self.grid.clone());
        }

        #[cfg(feature = "nova")]
        if self.spirit_request {
            if let Some(val) = self.spirit_value.take() {
                self.stack.push(val);
                self.spirit_request = false;
                self.output.push(format!(
                    "SPIRIT: Received input: {}",
                    self.stack.last().unwrap()
                ));
            } else {
                return false; // Wait for spirit input
            }
        }

        true
    }

    /// Determines if time is frozen and updates energy costs.
    fn update_time_and_energy(&mut self) -> bool {
        #[cfg(feature = "nova")]
        let time_frozen = if self.chronostasis_timer > 0 {
            self.chronostasis_timer -= 1;
            true
        } else {
            false
        };
        #[cfg(not(feature = "nova"))]
        let time_frozen = false;

        #[cfg(feature = "nova")]
        self.blackbox.record(
            &self.dna,
            self.ip,
            &self.stack,
            self.energy,
            self.context_loc,
        );

        #[cfg(feature = "nova")]
        {
            let (cy, cx) = self.context_loc;
            let modifier = self.biome_grid[cy][cx].energy_cost_modifier();
            let base_cost = 1.0 * modifier;
            let int_cost = base_cost.floor() as i64;
            let prob = base_cost - int_cost as f64;
            let mut rng = rand::thread_rng();
            let extra = if rng.gen_bool(prob) { 1 } else { 0 };
            self.energy -= int_cost + extra;
        }
        #[cfg(not(feature = "nova"))]
        {
            self.energy -= 1;
        }

        time_frozen
    }

    fn decay_effects(&mut self) {
        // Decay execution trail
        for val in self.execution_trail.iter_mut() {
            if *val > 0 {
                *val = val.saturating_sub(5);
            }
        }

        // Decay reactor flash
        #[cfg(feature = "nova")]
        for row in self.reactor_flash.iter_mut() {
            let row: &mut Vec<u8> = row;
            for val in row.iter_mut() {
                let v: &mut u8 = val;
                if *v > 0 {
                    *v = v.saturating_sub(10);
                }
            }
        }

        // Process Visual Effects
        self.visual_effects.retain_mut(|effect| match effect {
            VisualEffect::Lightning { ref mut ttl, .. } => {
                *ttl = ttl.saturating_sub(1);
                *ttl > 0
            }
            VisualEffect::Spark { ref mut ttl, .. } => {
                *ttl = ttl.saturating_sub(1);
                *ttl > 0
            }
        });
    }

    fn process_buffs_and_status(&mut self) -> usize {
        #[cfg(feature = "nova")]
        {
            // Process Buffs
            let mut expired = Vec::new();
            for (buff, duration) in self.buffs.iter_mut() {
                if *duration > 0 {
                    *duration -= 1;
                }
                if *duration == 0 {
                    let s: String = (*buff).clone();
                    expired.push(s);
                }
            }
            for buff in expired {
                self.buffs.remove(&buff);
                self.output.push(format!("BUFF EXPIRED: {}", buff));
            }
        }

        #[cfg(feature = "nova")]
        let iterations = if self.phase == nova::Phase::Flux {
            self.energy -= 1;
            2
        } else if self.buffs.contains_key("Sour") {
            2 // Haste Buff
        } else {
            1
        };

        #[cfg(not(feature = "nova"))]
        let iterations = 1;

        iterations
    }

    fn execute_main_loop(&mut self, iterations: usize, time_frozen: bool) {
        for _ in 0..iterations {
            let helix_len = self.dna.helix.strands.len();
            if self.ip.0 >= helix_len {
                self.halted = true;
                return;
            }

            let strand_len = self.dna.helix.strands[self.ip.0].genes.len();
            if self.ip.1 >= strand_len {
                self.ip.0 += 1;
                self.ip.1 = 0;
                return;
            }

            #[cfg(feature = "nova")]
            {
                if !time_frozen && self.check_telomeres() {
                    return;
                }
                if self.epigenome.contains(&self.ip) {
                    self.ip.1 += 1;
                    continue;
                }
                self.active_organelle_kind = None;
            }

            // Clone gene info to release borrow on self.dna
            let (gene_op, gene_args) = {
                let gene = &self.dna.helix.strands[self.ip.0].genes[self.ip.1];
                (gene.op.clone(), gene.args.clone())
            };

            let jump_target = self.execute_gene(gene_op, &gene_args);

            if let Some(target) = jump_target {
                self.ip = target;
            } else {
                #[cfg(feature = "nova")]
                {
                    if self.direction >= 0 {
                        self.ip.1 += 1;
                    } else if self.ip.1 > 0 {
                        self.ip.1 -= 1;
                    } else {
                        // Move to previous non-empty strand
                        let start_strand = self.ip.0;
                        let helix_len = self.dna.helix.strands.len();
                        loop {
                            if self.ip.0 > 0 {
                                self.ip.0 -= 1;
                            } else {
                                self.ip.0 = helix_len.saturating_sub(1);
                            }

                            let len = self.dna.helix.strands[self.ip.0].genes.len();
                            if len > 0 {
                                self.ip.1 = len - 1;
                                break;
                            }

                            if self.ip.0 == start_strand {
                                // All strands empty or cycled back
                                break;
                            }
                        }
                    }
                }
                #[cfg(not(feature = "nova"))]
                {
                    self.ip.1 += 1;
                }
            }
        }
    }

    fn process_post_tick(&mut self, time_frozen: bool) {
        #[cfg(feature = "nova")]
        if !time_frozen {
            self.process_symbiotes();
        }

        #[cfg(feature = "nova")]
        if !time_frozen {
            self.process_organelles();
        }
    }

    /// Advances the simulation by one tick.
    ///
    /// The execution order is:
    /// 1.  **Spirit Input**: Process external user input if requested (`OpCode::Spirit`).
