    ///
    /// ```text
    /// // Example usage of step
    /// ```
    ///
    /// ## Examples
    ///
    /// ```text
    /// // Example usage of step
    /// ```
    ///
    /// ## Examples
    ///
    /// ```text
    /// // Example usage of step
    /// ```
    ///
    /// ## Examples
    ///
    /// ```text
    /// // Example usage of step
    /// ```
    ///
    /// ## Examples
    ///
    /// ```text
    /// // Example usage of step
    /// ```
    ///
    /// ## Examples
    ///
    /// ```text
    /// // Example usage of step
    /// ```
    pub fn step(&mut self) {
        if !self.pre_tick_updates() {
            return;
        }

        let time_frozen = self.update_time_and_energy();
        self.decay_effects();

        #[cfg(feature = "nova")]
        self.handle_input_interrupts();

        // Separate paradox state to appease borrow checker
        let mut paradox = std::mem::take(&mut self.paradox);
        paradox.tick(self);
        self.paradox = paradox;

        self.process_subsystems(time_frozen);
        self.process_nova_environment(time_frozen);

        if self.process_chaos_and_events(time_frozen) {
            // Starved or dead
            return;
        }

        let iterations = self.process_buffs_and_status();
        self.execute_main_loop(iterations, time_frozen);
        self.process_post_tick(time_frozen);
    }

    #[cfg(feature = "oracle")]
    fn consult_oracle(&self, op: &OpCode) -> bool {
        if !self.regulatory_mode {
            return false;
        }

        let op_name = op.to_string();
        // Query: censor("op_name")
        let goal = Value::Junction(
            JunctionType::Any,
            vec![Value::Str("censor".to_string()), Value::Str(op_name)],
        );

        let mut solutions = Vec::new();
        oracle::solve(
            &[goal],
            HashMap::new(),
            &self.knowledge_base,
            self,
            &mut solutions,
            0,
        );

        !solutions.is_empty()
    }

    /// Executes a single gene operation.
    ///
    /// Returns `Some((new_strand, new_gene))` if a jump occurred, or `None` to continue sequentially.
    ///
    /// # Errors
    ///
    /// Runtime errors (stack underflow, type mismatch, division by zero) are silent:
    /// they push an error message to `self.output` and return gracefully, mimicking biological resilience.
    fn execute_gene(&mut self, op: OpCode, args: &[Nucleotide]) -> Option<(usize, usize)> {
        #[cfg(feature = "oracle")]
        if self.consult_oracle(&op) {
            self.output.push(format!("CENSORED: {}", op));
            return None;
        }

        // Record execution count (Lazy resize)
        if self.gene_execution_counts.len() <= self.ip.0 {
            self.gene_execution_counts.resize(self.ip.0 + 1, Vec::new());
        }
        if self.gene_execution_counts[self.ip.0].len() <= self.ip.1 {
            self.gene_execution_counts[self.ip.0].resize(self.ip.1 + 1, 0);
        }
        self.gene_execution_counts[self.ip.0][self.ip.1] += 1;

        // Mark trail
        let (cy, cx) = self.context_loc;
        if cy < GRID_SIZE && cx < GRID_SIZE {
            self.execution_trail[cy * GRID_SIZE + cx] = 255;
        }

        if self.recursion_depth > MAX_RECURSION_DEPTH {
            self.output
                .push("Error: Recursion limit exceeded".to_string());
            return None;
        }
        self.recursion_depth += 1;

        #[cfg(feature = "nova")]
        let (effective_op, effective_args) = {
            let mut final_op = if let Some(dialect) = self.dialects.get(&self.ip.0) {
                if let Some(mapped) = dialect.get(&op) {
                    (*mapped).clone()
                } else {
                    self.remap_table.get(&op).unwrap_or(&op).clone()
                }
            } else {
                self.remap_table.get(&op).unwrap_or(&op).clone()
            };

            // Babel Drift
            if self.babel_state.integrity < 1.0 {
                let mut rng = rand::thread_rng();
                if rng.gen_bool(1.0 - self.babel_state.integrity) {
                    if let Some(chaos_op) = self.babel_state.chaos_map.get(&final_op) {
                        final_op = Clone::clone(chaos_op);
                    } else if self.babel_state.integrity < 0.2 && rng.gen_bool(0.1) {
                        // Total breakdown
                        final_op = self.babel_state.get_random_op();
                    }
                }
            }

            let mut final_args = args.to_vec();
            if let Some((new_op, new_args)) =
                nova_chromatin::apply_chromatin_effect(self, final_op.clone(), &final_args)
            {
                final_op = new_op;
                final_args = new_args;
            }

            (final_op, final_args)
        };
        #[cfg(not(feature = "nova"))]
        let (effective_op, effective_args) = (op, args.to_vec());

        let result = self.execute_gene_inner(effective_op.clone(), &effective_args);
        self.recursion_depth -= 1;

        // Track last executed gene for Memetics
        #[cfg(feature = "nova")]
        {
            self.last_gene = Some(crate::ast::Gene {
                op,
                args: args.to_vec(),
            });
        }

        result
    }

