    /// ```
    pub fn get_circular_coords(&self, cx: i64, cy: i64, r: i64) -> Vec<(usize, usize)> {
        let mut coords = Vec::with_capacity(
            (r.saturating_mul(r).saturating_mul(4) as usize).min(GRID_SIZE * GRID_SIZE),
        );
        iterate_circle(
            #[cfg(feature = "nova")]
            self.topology,
            cx,
            cy,
            r,
            |x, y| coords.push((x, y)),
        );
        coords
    }

    pub(crate) fn execute_gene_inner(
        &mut self,
        op: OpCode,
        args: &[Nucleotide],
    ) -> Option<(usize, usize)> {
        #[cfg(feature = "nova")]
        match self.exec_core_op(op.clone(), args) {
            crate::vm::ops::Dispatch::Handled => return None,
            crate::vm::ops::Dispatch::Jump(i, j) => return Some((i, j)),
            crate::vm::ops::Dispatch::Unhandled => {}
        }

        #[cfg(feature = "nova")]
        match self.exec_nova_dispatch(op.clone(), args) {
            crate::vm::ops::Dispatch::Handled => return None,
            crate::vm::ops::Dispatch::Jump(i, j) => return Some((i, j)),
            crate::vm::ops::Dispatch::Unhandled => {}
        }

        match op {
            #[cfg(feature = "cortex")]
            OpCode::Link | OpCode::Sever | OpCode::Spark | OpCode::Sense | OpCode::Gate => {
                cortex::exec_cortex_op(self, op, args);
                None
            }

            #[cfg(feature = "oracle")]
            OpCode::FindAll => self.exec_findall_op(),

            #[cfg(feature = "oracle")]
            OpCode::Assert
            | OpCode::Rule
            | OpCode::Retract
            | OpCode::Query
            | OpCode::Augury
            | OpCode::Divinate
            | OpCode::Seek
            | OpCode::Manifest
            | OpCode::Unify
            | OpCode::PrologCall
            | OpCode::Censor => oracle::exec_oracle_op(self, op, args),

            #[cfg(feature = "resonance")]
            OpCode::Pluck | OpCode::Oscillate | OpCode::Hear | OpCode::Scream => {
                resonance::exec_resonance_op(self, op, args);
                None
            }

            #[cfg(all(feature = "nova", feature = "resonance"))]
            OpCode::Sift => {
                nova_cymatics::exec_sift(self, op, args);
                None
            }

            #[cfg(all(feature = "nova", feature = "resonance"))]
            OpCode::Reshape => {
                nova_cymatics::exec_reshape(self, op, args);
                None
            }

            #[cfg(feature = "biophysics")]
            OpCode::NeuroGenesis
            | OpCode::Stimulate
            | OpCode::Dendrite
            | OpCode::Axon
            | OpCode::Receptor
            | OpCode::NeuroCoupling
            | OpCode::NeuroSynapse => {
                neuron::exec_biophysics_op(self, op, args);
                None
            }

            #[cfg(feature = "silicon")]
            OpCode::Conduct
            | OpCode::Wire
            | OpCode::Pulse
            | OpCode::Silicon
            | OpCode::Construct
            | OpCode::LogicGate
            | OpCode::PinIn
            | OpCode::PinOut
            | OpCode::Emitter
            | OpCode::Receiver
            | OpCode::Latch
            | OpCode::DAC
            | OpCode::ADC
            | OpCode::Trace
            | OpCode::Fabricate => {
                silicon::exec_silicon_op(self, op, args);
                None
            }

            #[cfg(feature = "elektra")]
            OpCode::Electrogenesis
            | OpCode::Induction
            | OpCode::WireGrowth
            | OpCode::CircuitBreaker
            | OpCode::Battery
            | OpCode::Ground
            | OpCode::SenseVolt
            | OpCode::Shock
            | OpCode::TeslaCoil
            | OpCode::Diode
            | OpCode::Transistor
            | OpCode::Muscle
            | OpCode::Sensor
            | OpCode::Patch
            | OpCode::Electrophoresis
            | OpCode::Modulate
            | OpCode::Lightning => elektra::exec_elektra_op(self, op, args),

            #[cfg(all(feature = "elektra", feature = "nova"))]
            OpCode::Galvanize | OpCode::Railgun => elektra::exec_elektra_op(self, op, args),

            #[cfg(feature = "hive")]
            OpCode::HiveBind | OpCode::HiveSend | OpCode::HiveRecv | OpCode::HiveClose => {
                hive::exec_hive_op(self, op, args);
                None
            }

            #[cfg(feature = "git")]
            OpCode::Ancestry | OpCode::Excavate | OpCode::Evolution => {
                git::exec_git_op(self, op, args)
            }

            #[cfg(feature = "git")]
            OpCode::GitHistory | OpCode::GitDiffWorkspace => {
                git_associates::exec_git_associates_op(self, op, args)
            }

            #[cfg(feature = "phylogeny")]
            OpCode::Crawl
            | OpCode::Sequencing
            | OpCode::PhyloSynthesize
            | OpCode::PhyloInfect
            | OpCode::Shell => {
                phylogeny::exec_phylogeny_op(self, op, args);
                None
            }

            OpCode::ChimeraForge => {
                self.energy = self.energy.saturating_add(500);
                self.output.push(
                    "CHIMERA FORGE: The anvil strikes! A new esoteric construct is born from the flames. ⚛️".to_string(),
                );
                None
            }
            OpCode::PrologueMadScientist => {
                self.output.push(
                    "PROLOGUE: Evolving chimera-lang... Mad Scientist mode activated!".to_string(),
                );
                None
            }
            OpCode::MadScientist => {
                self.prologue_state.active = true;
                self.prologue_state.orca_mode = true;
                self.glitch_level = 100.0;
                self.energy = self.energy.saturating_add(1000);
                self.output.push(
                    "MAD SCIENTIST: Injecting extreme chaotic mutations and Orca signal bursts! ⚛️"
                        .to_string(),
                );

                let mut rng = rand::thread_rng();
                use rand::Rng;
                for y in 0..crate::vm::GRID_SIZE {
                    for x in 0..crate::vm::GRID_SIZE {
                        if rng.gen_bool(0.15) {
                            let runes =
                                ["M", "ζ", "₣", "⚡", "O", "?", "!", "*", "~", "♻", "P", "c"];
                            let rune = runes[rng.gen_range(0..runes.len())];
                            self.grid[y][x] = crate::vm::Value::Str(rune.to_string());
                        }
                    }
                }
                None
            }
            OpCode::Nop => None,

            OpCode::Unknown(name) => self.handle_unknown_opcode(&name),

            _ => {
                #[cfg(not(feature = "nova"))]
                {
                    match self.exec_core_op(op.clone(), args) {
                        crate::vm::ops::Dispatch::Handled => return None,
                        crate::vm::ops::Dispatch::Jump(i, j) => return Some((i, j)),
                        crate::vm::ops::Dispatch::Unhandled => {}
                    }
                }

                self.output
                    .push(format!("Error: Unimplemented OpCode {}", op));
                None
            }
        }
    }

